// Agrega las filas de la API en KPIs diarios y acumulados
const INICIO = '2026-08-31', FIN = '2026-09-24';
const PRESUPUESTO = 2000, OBJETIVO = 200, CPL_ALERTA = 15;

const filas = [];
for (const item of $input.all()) {
  for (const r of (item.json.results || [])) {
    filas.push({
      campania: r.campaign.name,
      estado: r.campaign.status,
      fecha: r.segments.date,
      impresiones: Number(r.metrics.impressions || 0),
      clics: Number(r.metrics.clicks || 0),
      coste: Number(r.metrics.costMicros || 0) / 1e6,
      conversiones: Number(r.metrics.conversions || 0),
      isPerdidaPresupuesto: Number(r.metrics.searchBudgetLostImpressionShare || 0),
    });
  }
}

const ayer = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
const suma = (arr) => arr.reduce((a, f) => ({
  impresiones: a.impresiones + f.impresiones, clics: a.clics + f.clics,
  coste: a.coste + f.coste, conversiones: a.conversiones + f.conversiones,
}), {impresiones: 0, clics: 0, coste: 0, conversiones: 0});

const porCampania = {};
for (const f of filas) {
  if (!porCampania[f.campania]) porCampania[f.campania] = [];
  porCampania[f.campania].push(f);
}
const acumCampanias = Object.keys(porCampania).map((n) => {
  const t = suma(porCampania[n]);
  return {campania: n, ...t, cpl: t.conversiones ? t.coste / t.conversiones : null,
          estado: porCampania[n][0].estado,
          isPerdidaPresupuesto: Math.max(...porCampania[n].map((x) => x.isPerdidaPresupuesto))};
});
const ayerCampanias = Object.keys(porCampania).map((n) => {
  const t = suma(porCampania[n].filter((f) => f.fecha === ayer));
  return {campania: n, ...t};
});

const acum = suma(filas), deAyer = suma(filas.filter((f) => f.fecha === ayer));
const diasCorridos = Math.max(1, Math.round((new Date(ayer) - new Date(INICIO)) / 86400000) + 1);
const diasRestantes = Math.max(0, Math.round((new Date(FIN) - new Date()) / 86400000));
const proyeccion = acum.conversiones / diasCorridos * (diasCorridos + diasRestantes);

const avisos = [];
for (const c of acumCampanias) {
  const a = ayerCampanias.find((x) => x.campania === c.campania);
  if (c.estado === 'ENABLED' && a && a.impresiones === 0)
    avisos.push('«' + c.campania + '» no tuvo impresiones ayer.');
  if (c.isPerdidaPresupuesto > 0.2)
    avisos.push('«' + c.campania + '» pierde el ' +
      (c.isPerdidaPresupuesto * 100).toFixed(0) + '% de impresiones por presupuesto: ' +
      'considerar subirlo o moverlo desde otra campaña.');
}
const cpl = acum.conversiones ? acum.coste / acum.conversiones : 0;
if (cpl > CPL_ALERTA) avisos.push('CPL acumulado de ' + cpl.toFixed(2) + ' €, por encima del umbral.');
if (acum.coste > 150 && acum.conversiones === 0)
  avisos.push('Más de ' + acum.coste.toFixed(0) + ' € sin conversiones: revisar el seguimiento.');
const ritmoNecesario = diasRestantes ? (PRESUPUESTO - acum.coste) / diasRestantes : 0;
if (deAyer.coste > 0 && ritmoNecesario > 0 && deAyer.coste < ritmoNecesario * 0.6)
  avisos.push('Ritmo de gasto bajo: ayer ' + deAyer.coste.toFixed(2) + ' € frente a ' +
    ritmoNecesario.toFixed(2) + ' €/día necesarios.');
if (diasRestantes <= 7 && acum.conversiones < OBJETIVO * 0.6)
  avisos.push('Quedan ' + diasRestantes + ' días y llevamos ' +
    acum.conversiones.toFixed(0) + ' de ' + OBJETIVO + ' registros.');

return [{json: {
  ayer, diasRestantes, diasCorridos, proyeccion, avisos,
  acum: {...acum, cpl}, deAyer, acumCampanias, ayerCampanias,
  pctPresupuesto: acum.coste / PRESUPUESTO * 100,
  presupuesto: PRESUPUESTO, objetivo: OBJETIVO,
  terminos: ($('Google Ads · términos de ayer').all()[0]?.json?.results || []).map((r) => ({
    termino: r.searchTermView.searchTerm,
    clics: Number(r.metrics.clicks || 0),
    coste: Number(r.metrics.costMicros || 0) / 1e6,
    conversiones: Number(r.metrics.conversions || 0),
  })),
}}];

const d = $json;
const eur = (v) => v.toFixed(2).replace('.', ',') + ' €';
const num = (v) => String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

let h = '<div style="font-family:system-ui,Arial,sans-serif;max-width:780px;color:#1a1a1a">';
h += '<h2 style="margin:0 0 4px">OutThink 2026 · informe del ' + d.ayer + '</h2>';
h += '<p style="color:#666;margin:0 0 20px">Quedan ' + d.diasRestantes +
     ' días para el evento (24 de septiembre).</p>';

h += '<div style="display:flex;gap:12px;margin-bottom:24px;flex-wrap:wrap">';
const tarjeta = (etiqueta, valor, sub) =>
  '<div style="flex:1;min-width:150px;background:#f6f7f9;border-radius:8px;padding:14px 16px">' +
  '<div style="color:#666;font-size:12px;text-transform:uppercase;letter-spacing:.04em">' + etiqueta + '</div>' +
  '<div style="font-size:26px;font-weight:700;margin-top:4px">' + valor + '</div>' +
  (sub ? '<div style="color:#888;font-size:12px;margin-top:2px">' + sub + '</div>' : '') + '</div>';
h += tarjeta('Registros', Math.round(d.acum.conversiones), 'objetivo ' + d.objetivo + '+');
h += tarjeta('CPL', d.acum.cpl ? eur(d.acum.cpl) : '—', 'coste por registro');
h += tarjeta('Invertido', eur(d.acum.coste), d.pctPresupuesto.toFixed(0) + '% de ' + eur(d.presupuesto));
h += tarjeta('Proyección', Math.round(d.proyeccion), 'al ritmo actual');
h += '</div>';

if (d.avisos.length) {
  h += '<div style="background:#fff5f5;border-left:4px solid #d64545;padding:12px 16px;margin-bottom:24px;border-radius:0 6px 6px 0">';
  h += '<strong>Requiere atención</strong><ul style="margin:8px 0 0;padding-left:18px">';
  for (const a of d.avisos) h += '<li style="margin:4px 0">' + a + '</li>';
  h += '</ul></div>';
}

const tabla = (cabeceras, filas) => {
  let t = '<table style="border-collapse:collapse;width:100%;font-size:14px;margin-bottom:24px">';
  t += '<tr>' + cabeceras.map((c, i) =>
    '<th style="padding:8px 10px;border-bottom:2px solid #e5e5e5;background:#fafafa;text-align:' +
    (i ? 'right' : 'left') + '">' + c + '</th>').join('') + '</tr>';
  for (const f of filas) {
    t += '<tr>' + f.map((c, i) =>
      '<td style="padding:8px 10px;border-bottom:1px solid #eee;text-align:' +
      (i ? 'right' : 'left') + '">' + c + '</td>').join('') + '</tr>';
  }
  return t + '</table>';
};

h += '<h3>Acumulado por campaña</h3>';
h += tabla(['Campaña', 'Impresiones', 'Clics', 'CTR', 'Coste', 'Registros', 'CPL'],
  d.acumCampanias.map((c) => [c.campania, num(c.impresiones), num(c.clics),
    (c.impresiones ? (c.clics / c.impresiones * 100).toFixed(2) : '0,00') + '%',
    eur(c.coste), Math.round(c.conversiones), c.cpl ? eur(c.cpl) : '—']));

h += '<h3>Ayer</h3>';
h += tabla(['Campaña', 'Impresiones', 'Clics', 'Coste', 'Registros'],
  d.ayerCampanias.map((c) => [c.campania, num(c.impresiones), num(c.clics),
    eur(c.coste), Math.round(c.conversiones)]));

if (d.terminos.length) {
  h += '<h3>Términos de búsqueda de ayer</h3>';
  h += '<p style="color:#666;font-size:13px;margin:0 0 8px">Revisar y añadir como negativas ' +
       'los que no encajen con el perfil del evento.</p>';
  h += tabla(['Término', 'Clics', 'Coste', 'Registros'],
    d.terminos.map((t) => [t.termino, num(t.clics), eur(t.coste), Math.round(t.conversiones)]));
}

h += '<p style="color:#999;font-size:12px;border-top:1px solid #eee;padding-top:12px">' +
     'Generado automáticamente · Qualivo</p></div>';

return [{json: {
  html: h,
  asunto: 'OutThink 2026 · ' + Math.round(d.acum.conversiones) +
          (Math.round(d.acum.conversiones) === 1 ? ' registro · ' : ' registros · ') +
          d.diasRestantes + ' días' + (d.avisos.length ? ' · ' + d.avisos.length + ' aviso(s)' : ''),
  fila: {
    fecha: d.ayer,
    impresiones: d.deAyer.impresiones, clics: d.deAyer.clics,
    ctr: d.deAyer.impresiones ? +(d.deAyer.clics / d.deAyer.impresiones * 100).toFixed(2) : 0,
    cpc_medio: d.deAyer.clics ? +(d.deAyer.coste / d.deAyer.clics).toFixed(2) : 0,
    coste: +d.deAyer.coste.toFixed(2), conversiones: d.deAyer.conversiones,
    cpl: d.deAyer.conversiones ? +(d.deAyer.coste / d.deAyer.conversiones).toFixed(2) : 0,
    coste_acumulado: +d.acum.coste.toFixed(2),
    conversiones_acumuladas: d.acum.conversiones,
    pct_presupuesto: +d.pctPresupuesto.toFixed(1),
    proyeccion_registros: Math.round(d.proyeccion),
  },
}}];
